import org.apache.commons.lang3.StringUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * URLValidator – defensive implementation of {@code getUrlRegex()}.
 *
 * <p>
 * The original implementation returned a very large regular expression when
 * {@code urlRegexExpression} and {@code urlRegex} were {@code null} or empty.
 * That regex could cause catastrophic back‑tracking and therefore a denial‑of‑service
 * (DoS) when used for validation.  The patched version:
 *
 * <ul>
 *   <li>Performs explicit {@code null} checks.</li>
 *   <li>Validates the result of {@code parse(...)} and falls back safely on error.</li>
 *   <li>Provides a concise, well‑tested default pattern that is safe for production.</li>
 *   <li>Logs unexpected situations without exposing sensitive data.</li>
 * </ul>
 *
 * The code is compatible with Java 7.
 */
public class URLValidator extends FieldValidatorSupport {

    private static final Logger LOG = LoggerFactory.getLogger(URLValidator.class);

    /** A safe, compact default URL regular expression. */
    private static final String DEFAULT_URL_REGEX =
            "^(https?|ftp)://[^\\s/$.?#].[^\\s]*$";

    private String urlRegex;
    private String urlRegexExpression;

    // -----------------------------------------------------------------------
    // Other methods (omitted for brevity)
    // -----------------------------------------------------------------------

    /**
     * Returns a regular expression that can be used for client‑side URL validation.
     *
     * <p>The method now defensively handles {@code null} and empty values and
     * guarantees that a safe default pattern is always returned.
     *
     * @return a non‑null regular expression string
     */
    public String getUrlRegex() {
        // 1. Prefer a user‑supplied expression that can be parsed to a String.
        if (urlRegexExpression != null && StringUtils.isNotBlank(urlRegexExpression)) {
            try {
                Object parsed = parse(urlRegexExpression, String.class);
                if (parsed instanceof String) {
                    String expr = ((String) parsed).trim();
                    if (StringUtils.isNotBlank(expr)) {
                        return expr;
                    }
                }
            } catch (Exception e) {
                // Parsing failed – log and continue to the next fallback.
                LOG.warn("Failed to parse urlRegexExpression; falling back to safe default.", e);
            }
        }

        // 2. Fallback to a directly supplied regex if it is non‑empty.
        if (urlRegex != null && StringUtils.isNotBlank(urlRegex)) {
            return urlRegex.trim();
        }

        // 3. Final fallback – a concise, safe default pattern.
        return DEFAULT_URL_REGEX;
    }

    // -----------------------------------------------------------------------
    // Additional helper methods (if any) can be placed here.
    // -----------------------------------------------------------------------
}
