```java
static public File allocateFile(File dir, String name) {
    if (dir == null) {
        throw new IllegalArgumentException("Target directory must not be null");
    }
    if (name == null) {
        throw new IllegalArgumentException("File name must not be null");
    }

    // Strip query string if present (e.g., "file.txt?param")
    int q = name.indexOf('?');
    if (q > 0) {
        name = name.substring(0, q);
    }

    // Normalize the supplied name and reject path‑traversal attempts
    // Convert back‑slashes to forward‑slashes to handle Windows paths
    String normalizedName = name.replace('\\', '/');
    // Collapse any "." or ".." segments
    java.nio.file.Path namePath = java.nio.file.Paths.get(normalizedName).normalize();

    // After normalization the path must be a single name (no parent elements)
    for (Path part : namePath) {
        String partStr = part.toString();
        if (partStr.equals("..") || partStr.equals(".")) {
            throw new IllegalArgumentException("Path traversal elements are not allowed in file name: " + name);
        }
        if (partStr.contains("/") || partStr.contains("\\")) {
            // should never happen because we split on path elements, but guard anyway
            throw new IllegalArgumentException("Invalid path separator in file name: " + name);
        }
    }

    // Ensure the resulting name does not contain any separator characters
    String safeName = namePath.getFileName().toString();

    // Build the file inside the target directory
    File file = new File(dir, safeName);

    // Double‑check using canonical paths that the file really resides under dir
    try {
        java.nio.file.Path dirPath = dir.getCanonicalFile().toPath();
        java.nio.file.Path filePath = file.getCanonicalFile().toPath();
        if (!filePath.startsWith(dirPath)) {
            throw new IllegalArgumentException("Resulting file escapes the target directory");
        }
    } catch (java.io.IOException e) {
        // If we cannot resolve canonical paths, fail fast
        throw new IllegalArgumentException("Unable to resolve file path", e);
    }

    // Determine a unique name if the file already exists
    int dot = safeName.lastIndexOf('.');
    String prefix = (dot < 0) ? safeName : safeName.substring(0, dot);
    String suffix = (dot < 0) ? "" : safeName.substring(dot);
    int index = 2;
    while (file.exists()) {
        file = new File(dir, prefix + "-" + index++ + suffix);
    }

    // Ensure parent directories exist
    File parent = file.getParentFile();
    if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
        throw new IllegalStateException("Failed to create directories for " + parent);
    }

    return file;
}
