protected void extractFile(final File srcF, final File dir, final InputStream compressedInputStream,
        final String entryName, final Date entryDate, final boolean isDirectory,
        final Integer mode, String symlinkDestination) throws IOException, ArchiverException {

    // Resolve the target file relative to the destination directory
    final File target = FileUtils.resolveFile(dir, entryName);

    // ----- Zip‑Slip protection -----
    // Resolve both paths to their canonical (real) form and compare.
    // If the target is not a child of the destination directory we abort.
    final Path canonicalDir = dir.getCanonicalFile().toPath();
    final Path canonicalTarget = target.getCanonicalFile().toPath();

    if (!canonicalTarget.startsWith(canonicalDir)) {
        throw new ArchiverException(
                "Entry is outside of the target directory (entryName=" + entryName + ")");
    }

    // Do not allow a regular file to overwrite an existing symbolic link.
    if (StringUtils.isEmpty(symlinkDestination) && Files.isSymbolicLink(canonicalTarget)) {
        throw new ArchiverException(
                "Refusing to overwrite existing symbolic link (entryName=" + entryName + ")");
    }
    // --------------------------------

    try {
