    /**
     * Normalises a URI path.
     * <p>
     * The original implementation only stripped excess leading slashes.
     * It failed to guarantee that a path always starts with a single '/'.
     * As a result, a path such as {@code "example.com"} could be interpreted
     * as a host component when the URI is later built, leading to security
     * issues (e.g., URL spoofing).
     * </p>
     * This implementation:
     * <ul>
     *   <li>Ensures the returned path is never {@code null} (returns {@code null}
     *       only when the input is {@code null}).</li>
     *   <li>Guarantees a single leading '/' – adding one when missing.</li>
     *   <li>Collapses any number of leading '/' characters to exactly one.</li>
     *   <li>Handles edge‑cases such as an empty string or a string consisting
     *       solely of slashes, returning {@code "/" } in those cases.</li>
     * </ul>
     *
     * @param path the raw path component, may be {@code null}
     * @return a normalised path starting with a single '/', or {@code null}
     *         if the input was {@code null}
     */
    private static String normalizePath(final String path) {
        if (path == null) {
            return null;
        }

        // Empty string -> treat as root path
        if (path.isEmpty()) {
            return "/";
        }

        int length = path.length();
        int firstNonSlash = 0;

        // Find the index of the first character that is not a '/'
        while (firstNonSlash < length && path.charAt(firstNonSlash) == '/') {
            firstNonSlash++;
        }

        // If the whole string is made of '/', return a single '/'
        if (firstNonSlash == length) {
            return "/";
        }

        // If there were no leading slashes, prepend one.
        // Otherwise, keep exactly one leading slash and the remainder.
        if (firstNonSlash == 0) {
            return "/" + path;
        } else {
            return "/" + path.substring(firstNonSlash);
        }
    }

