public class XPathBuilder extends ServiceSupport implements Expression, Predicate, NamespaceAware {

    private final ThreadLocal<Exchange> exchange = new ThreadLocal<Exchange>();
    private volatile Class<?> documentType = Document.class;

    // -------------------------------------------------------------------------
    // Secure XML parsing helpers
    // -------------------------------------------------------------------------

    /**
     * Parses the supplied {@link InputSource} into a {@link Document} using a
     * securely configured {@link DocumentBuilderFactory}. All features that
     * allow external DTDs, external entities or schema access are disabled.
     *
     * @param source the XML source to parse
     * @return a DOM {@link Document}
     * @throws Exception if parsing fails
     */
    private Document parseSecure(InputSource source) throws Exception {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

        // ---- Harden the factory against XXE and related attacks ----
        // General secure‑processing flag
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        // Disallow DOCTYPE declarations (prevents DTD based attacks)
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        // Disable external general entities
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        // Disable external parameter entities
        dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        // Completely block any external DTD or schema access
        dbf.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
        dbf.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

        // The factory must be namespace‑aware for XPath processing
        dbf.setNamespaceAware(true);

        DocumentBuilder builder = dbf.newDocumentBuilder();
        return builder.parse(source);
    }

    // -------------------------------------------------------------------------
    // Original logic, now hardened against XXE
    // -------------------------------------------------------------------------

    /**
     * Retrieves a document (or a securely parsed {@link Document}) from the
     * message body. The method now ensures that any XML supplied as a {@link String},
     * {@link InputStream}, {@link InputSource} or {@link WrappedFile} is parsed with
     * external entity resolution disabled.
     *
     * @param exchange the current exchange
     * @param body     the message body
     * @return a {@link Document} or the original body if it cannot be converted
     * @throws Exception if a required conversion fails
     */
    protected Object doGetDocument(Exchange exchange, Object body) throws Exception {
        if (body == null) {
            return null;
        }

        // If the body is already a DOM Document, return it directly – it is safe.
        if (body instanceof Document) {
            return body;
        }

        Class<?> type = getDocumentType(); // default is Document.class
        Exception conversionCause = null;
        Object answer = null;

        // -----------------------------------------------------------------
        // 1. Try the Camel type converter first (e.g., body already a Document)
        // -----------------------------------------------------------------
        if (type != null) {
            try {
                answer = exchange.getContext().getTypeConverter().convertTo(type, exchange, body);
                if (answer != null) {
                    // If the conversion already gave us a Document, we are done.
                    if (answer instanceof Document) {
                        return answer;
                    }
                }
            } catch (Exception e) {
                conversionCause = e; // remember for later error handling
            }
        }

        // -----------------------------------------------------------------
        // 2. Fallback handling – securely parse XML from known sources
        // -----------------------------------------------------------------
        if (answer == null) {
            if (body instanceof WrappedFile) {
                // Convert the wrapped file to an InputStream and parse securely
                InputStream is = exchange.getContext().getTypeConverter()
                        .convertTo(InputStream.class, exchange, body);
                if (is != null) {
                    answer = parseSecure(new InputSource(is));
                }
            } else if (body instanceof BeanInvocation) {
                BeanInvocation bi = exchange.getContext().getTypeConverter()
                        .convertTo(BeanInvocation.class, exchange, body);
                if (bi != null && bi.getArgs() != null && bi.getArgs().length == 1 && bi.getArgs()[0] == null) {
