        } else if (answer == null) {
            // Conversion failed – re‑throw the original cause if we have one,
            // otherwise throw a generic NoTypeConversionAvailableException.
            if (conversionCause != null) {
                throw conversionCause;
            } else {
                throw new NoTypeConversionAvailableException(body, type);
