/**
 * Secure implementation of an ObjectArray codec.
 *
 * <p>
 * The original implementation relied on Fastjson's {@code parseArray} method
 * with a component type that could be any class supplied by the caller.  This
 * allowed an attacker to supply a malicious class (e.g. one that triggers
 * RMI look‑ups) and achieve remote code execution via Fastjson's deserialization
 * gadget chain.  To mitigate this, the codec now enforces a strict whitelist of
 * safe component types.  Any attempt to deserialize an array whose component
 * type is not explicitly allowed results in an {@link IllegalArgumentException}.
 * </p>
 *
 * <p>
 * The whitelist includes primitive types, their wrapper classes, {@link String},
 * and a few common number types.  This set can be extended if the application
 * requires additional safe types.
 * </p>
 */
public class ObjectArrayCodec implements ObjectSerializer, ObjectDeserializer {

    /** Whitelisted component classes that are safe to deserialize. */
    private static final Set<Class<?>> ALLOWED_COMPONENT_TYPES = Collections.unmodifiableSet(
            new HashSet<>(Arrays.asList(
                    Boolean.class, Boolean.TYPE,
                    Byte.class, Byte.TYPE,
                    Short.class, Short.TYPE,
                    Integer.class, Integer.TYPE,
                    Long.class, Long.TYPE,
                    Float.class, Float.TYPE,
                    Double.class, Double.TYPE,
                    Character.class, Character.TYPE,
                    String.class,
                    java.math.BigDecimal.class,
                    java.math.BigInteger.class
            )));

    /**
     * Validates that the supplied component class is part of the whitelist.
     *
     * @param componentClass the class to validate
     * @throws IllegalArgumentException if the class is not allowed
     */
    private static void validateComponentClass(Class<?> componentClass) {
        if (componentClass == null || !ALLOWED_COMPONENT_TYPES.contains(componentClass)) {
            throw new IllegalArgumentException(
                    "Deserialization of component type " + componentClass + " is not allowed");
        }
    }

    @SuppressWarnings({ "unchecked", "rawtypes" })
    public <T> T deserialze(DefaultJSONParser parser, Type type, Object fieldName) {

        final JSONLexer lexer = parser.lexer;

        // ----- handle JSON null -------------------------------------------------
        if (lexer.token() == JSONToken.NULL) {
            lexer.nextToken(JSONToken.COMMA);
            return null;
        }

        // ----- handle JSON string literal (e.g. base64) ------------------------
        if (lexer.token() == JSONToken.LITERAL_STRING) {
            byte[] bytes = lexer.bytesValue();
            lexer.nextToken(JSONToken.COMMA);
            return (T) bytes;
        }

        // ----- determine component class ----------------------------------------
        Class componentClass;
        Type componentType;

        if (type instanceof GenericArrayType) {
            GenericArrayType gat = (GenericArrayType) type;
            componentType = gat.getGenericComponentType();

            if (componentType instanceof TypeVariable) {
                TypeVariable<?> typeVar = (TypeVariable<?>) componentType;
                Type contextType = parser.getContext().type;

                if (contextType instanceof ParameterizedType) {
                    ParameterizedType pt = (ParameterizedType) contextType;
                    Type raw = pt.getRawType();
                    Type actualType = null;

                    if (raw instanceof Class) {
                        TypeVariable<?>[] vars = ((Class<?>) raw).getTypeParameters();
                        for (int i = 0; i < vars.length; ++i) {
                            if (vars[i].getName().equals(typeVar.getName())) {
                                actualType = pt.getActualTypeArguments()[i];
                                break;
                            }
                        }
                    }

                    componentClass = (actualType instanceof Class)
                            ? (Class) actualType
                            : Object.class;
                } else {
                    // fallback to the first bound of the type variable
                    componentClass = TypeUtils.getClass(typeVar.getBounds()[0]);
                }
            } else {
                componentClass = TypeUtils.getClass(componentType);
            }
        } else {
            // plain array class, e.g. String[]
            Class<?> arrayClass = (Class<?>) type;
            componentClass = arrayClass.getComponentType();
            componentType = componentClass;
        }

        // ----- enforce whitelist -------------------------------------------------
        validateComponentClass(componentClass);

        // ----- parse the JSON array safely --------------------------------------
        JSONArray array = new JSONArray();
        parser.parseArray(componentClass, array, fieldName);
        return (T) toObjectArray(parser, componentClass, array);
    }

    // -------------------------------------------------------------------------
    // Existing helper methods (toObjectArray, serialize, etc.) remain unchanged.
    // -------------------------------------------------------------------------

}
